// Verify the sort disambiguation for equal-segment-count routes
// Simulate the sort for /workspace/:workspaceId/pages vs /workspace/:workspaceId/pages/:pageSlug+
const routes = [
  { pattern: '/workspace/:workspaceId/pages', constantSegmentCount: 2, restParam: null },
  { pattern: '/workspace/:workspaceId/pages/:pageSlug+', constantSegmentCount: 2, restParam: 'pageSlug' },
  { pattern: '/workspace/:workspaceId', constantSegmentCount: 1, restParam: null },
];
routes.sort((a, b) => {
  if (b.constantSegmentCount !== a.constantSegmentCount) return b.constantSegmentCount - a.constantSegmentCount;
  return (a.restParam ? 1 : 0) - (b.restParam ? 1 : 0);
});
console.log(routes.map(r => r.pattern));
"

